  assert SkillVfxDirectAuthoring.handles(spiral).stream().anyMatch(h->h.id().equals("radius"));
  var tx=SkillVfxDirectAuthoring.DragTransaction.begin(doc,spiral.id()).orElseThrow();tx.update(p->withLiteral(p,"radius",4));assert tx.release();assert doc.history().size()==1;assert literal(primitive(doc,spiral.id()),"radius")==4;assert doc.undo();assert literal(primitive(doc,spiral.id()),"radius")==1;assert doc.redo();assert literal(primitive(doc,spiral.id()),"radius")==4;
  var heightHandle=SkillVfxDirectAuthoring.handles(spiral).stream().filter(h->h.id().equals("height")).findFirst().orElseThrow();var heightProjection=new SkillVfxDirectAuthoring.Projection(new SkillVfxDirectAuthoring.Vec(1,0,0),new SkillVfxDirectAuthoring.Vec(0,1,0),new SkillVfxDirectAuthoring.Vec(0,0,1),new SkillVfxDirectAuthoring.Vec(0,0,-2),100,2);var heightDelta=SkillVfxDirectAuthoring.dragDelta(spiral,heightHandle,frame,heightProjection,0,10,false);assert heightDelta.y()>0;var heightEdited=SkillVfxDirectAuthoring.edit(spiral,heightHandle,0,2,false);assert literal(heightEdited,"height")==3;var heightTx=SkillVfxDirectAuthoring.DragTransaction.begin(doc,spiral.id()).orElseThrow();heightTx.update(p->SkillVfxDirectAuthoring.edit(p,heightHandle,0,2,false));assert heightTx.release()&&doc.history().size()==2;assert literal(primitive(doc,spiral.id()),"height")==3;var heightPreview=SkillVfxPreviewBuilder.convert(primitive(doc,spiral.id()),null);assert AbilityVfx.sample(heightPreview,frame,1,AbilityVfx.Quality.HIGH).stream().anyMatch(c->c.a().y()>0);assert doc.undo()&&literal(primitive(doc,spiral.id()),"height")==1;assert doc.redo()&&literal(primitive(doc,spiral.id()),"height")==3;
  var cancelled=SkillVfxDirectAuthoring.DragTransaction.begin(doc,spiral.id()).orElseThrow();cancelled.update(p->withLiteral(p,"height",5));assert cancelled.cancel();assert doc.history().size()==2;assert literal(primitive(doc,spiral.id()),"height")==3;
  var line=primitive(doc,"line-1");assert line.controls().size()==2;var lineTx=SkillVfxDirectAuthoring.DragTransaction.begin(doc,line.id()).orElseThrow();lineTx.update(p->withControls(p,List.of(new SkillVfxModel.Vec(2,0,0),p.controls().get(1))));assert lineTx.release();assert primitive(doc,line.id()).controls().getFirst().x()==2;
  var lineA=SkillVfxDirectAuthoring.handles(line).stream().filter(h->h.id().equals("control:0")).findFirst().orElseThrow();var lineB=SkillVfxDirectAuthoring.handles(line).stream().filter(h->h.id().equals("control:1")).findFirst().orElseThrow();var editedA=SkillVfxDirectAuthoring.edit(line,lineA,1,2,false);assert editedA.controls().getFirst().equals(new SkillVfxModel.Vec(line.controls().getFirst().x()+1,line.controls().getFirst().y()+2,line.controls().getFirst().z()));var editedB=SkillVfxDirectAuthoring.edit(line,lineB,3,0,true);assert editedB.controls().get(1).z()==line.controls().get(1).z()+3;assert SkillVfxDirectAuthoring.value(editedB,lineB).contains("Z");
  var bezier=primitive(doc,"bezier-1");assert bezier.controls().size()==3;var btx=SkillVfxDirectAuthoring.DragTransaction.begin(doc,bezier.id()).orElseThrow();btx.update(p->withControls(p,List.of(p.controls().get(0),new SkillVfxModel.Vec(0,2,.5),p.controls().get(2))));assert btx.release();assert primitive(doc,bezier.id()).controls().get(1).y()==2;
