  var noop=SkillVfxDirectAuthoring.DragTransaction.begin(doc,spiral.id()).orElseThrow();assert !noop.release()&&doc.history().size()==4;
  var projection=new SkillVfxDirectAuthoring.Projection(new SkillVfxDirectAuthoring.Vec(1,0,0),new SkillVfxDirectAuthoring.Vec(0,1,0),new SkillVfxDirectAuthoring.Vec(0,0,1),new SkillVfxDirectAuthoring.Vec(0,0,0),100,2);var handles=List.of(new SkillVfxDirectAuthoring.Handle("near","",new SkillVfxDirectAuthoring.Vec(0,0,2),SkillVfxDirectAuthoring.Handle.Kind.POINT),new SkillVfxDirectAuthoring.Handle("far","",new SkillVfxDirectAuthoring.Vec(0,0,4),SkillVfxDirectAuthoring.Handle.Kind.POINT));assert SkillVfxDirectAuthoring.pick(handles,projection,0,0,2).orElseThrow().handle().id().equals("near");
