  assert SkillVfxDirectAuthoring.fromFov(new SkillVfxDirectAuthoring.Vec(0,1,0),new SkillVfxDirectAuthoring.Vec(0,1,0),new SkillVfxDirectAuthoring.Vec(0,0,0),Math.PI/2,360,1).project(new SkillVfxDirectAuthoring.Vec(0,3,0)).isPresent();
  double s=Math.sqrt(.5);var rotatedCamera=SkillVfxDirectAuthoring.fromBasis(new SkillVfxDirectAuthoring.Vec(s,0,-s),new SkillVfxDirectAuthoring.Vec(0,1,0),new SkillVfxDirectAuthoring.Vec(s,0,s),new SkillVfxDirectAuthoring.Vec(-3,0,-3),200);var base=SkillVfxModel.defaults("drag",SkillVfxModel.PrimitiveType.LINE);var dragHandles=SkillVfxDirectAuthoring.worldHandles(base,frame);var dragX=dragHandles.stream().filter(h->h.id().equals("offsetX")).findFirst().orElseThrow();var dragZ=dragHandles.stream().filter(h->h.id().equals("offsetZ")).findFirst().orElseThrow();assert SkillVfxDirectAuthoring.dragDelta(base,dragX,frame,rotatedCamera,12,0,false).x()>0;assert SkillVfxDirectAuthoring.dragDelta(base,dragZ,frame,rotatedCamera,12,0,false).x()<0;var point=dragHandles.stream().filter(h->h.id().equals("control:0")).findFirst().orElseThrow();var plane=SkillVfxDirectAuthoring.dragDelta(base,point,frame,rotatedCamera,8,-5,false);assert Double.isFinite(plane.x())&&Double.isFinite(plane.y())&&(plane.x()!=0||plane.y()!=0);
  var offset=new SkillVfxModel.Primitive("offset",SkillVfxModel.PrimitiveType.SPIRAL,0,20,0xffffffff,.1,16,0,new SkillVfxModel.Vec(2,0,3),Math.PI/2,Map.of("radius",new SkillVfxModel.Literal(1),"turns",new SkillVfxModel.Literal(1)),List.of(),SkillVfxModel.Appearance.DEBUG_QUAD);var worldHandles=SkillVfxDirectAuthoring.worldHandles(offset,frame);var radius=worldHandles.stream().filter(h->h.id().equals("radius")).findFirst().orElseThrow();assert Math.abs(radius.position().x()-2)<1e-6&&Math.abs(radius.position().z()-2)<1e-6;var axisX=worldHandles.stream().filter(h->h.id().equals("offsetX")).findFirst().orElseThrow();assert Math.abs(axisX.position().x()-3)<1e-6&&Math.abs(axisX.position().z()-3)<1e-6;
  for(var type:SkillVfxModel.PrimitiveType.values()){var p=SkillVfxModel.defaults("progress-"+type,type);for(double progress:List.of(0d,.5d,1d))assert SkillVfxDirectAuthoring.guide(p,frame,null,progress).equals(AbilityVfx.sample(SkillVfxPreviewBuilder.convert(p,null),frame,progress,AbilityVfx.Quality.HIGH));}
  assert SkillVfxDirectAuthoring.axisDrag(new SkillVfxDirectAuthoring.Vec(0,0,0),SkillVfxDirectAuthoring.Handle.Kind.AXIS_Y,2).y()==2;
  var life=new SkillVfx3dAuthoringLifecycle();Object screen=new Object(),connection=new Object(),level=new Object();assert life.enter(screen,doc,connection,level,"test:world",spiral.id());assert life.valid(screen,doc,connection,level,"test:world",true);assert !life.valid(screen,doc,new Object(),level,"test:world",true);assert !life.valid(screen,doc,connection,level,"other",true);assert !life.valid(screen,new Object(),connection,level,"test:world",true);life.clear();assert !life.active();
  var action=new SkillVfxModel.GameplayAction("test","test",Map.of("radius","2.5"));var actionPrimitive=SkillVfxModel.defaults("action-circle",SkillVfxModel.PrimitiveType.CIRCLE).withValue("radius",new SkillVfxModel.FromGameplay(SkillVfxModel.ActionField.RADIUS));assert !SkillVfxDirectAuthoring.guide(actionPrimitive,frame,action).isEmpty();previewHistorySync();
  var lengthOnly=withControls(primitive(doc,"line-1"),List.of());doc.replacePrimitive(lengthOnly.id(),lengthOnly);int beforeMaterialize=doc.history().size();assert SkillVfxDirectAuthoring.materializeLine(doc,lengthOnly.id())&&primitive(doc,lengthOnly.id()).controls().size()==2&&doc.history().size()==beforeMaterialize+1;assert doc.undo()&&primitive(doc,lengthOnly.id()).controls().isEmpty();
  var layout=new SkillEditorLayout();java.util.function.ToIntFunction<String> font=text->text.codePointCount(0,text.length())*9;var compact=layout.previewPage(layout.bounds(640,360).preview(),false,"発動時","ベジェ曲線","プレイヤー周囲",true,"",font);assert compact.world().within(layout.bounds(640,360).preview())&&compact.world().width()>=88;
  try{var root=java.nio.file.Path.of("").toAbsolutePath();String editor=java.nio.file.Files.readString(root.resolve("devtools/src/client/java/io/github/gyai/projects/devtools/SkillEditorScreen.java")),authoring=java.nio.file.Files.readString(root.resolve("devtools/src/client/java/io/github/gyai/projects/devtools/skillvfx/ui/SkillVfx3dAuthoringScreen.java")),renderer=java.nio.file.Files.readString(root.resolve("devtools/src/client/java/io/github/gyai/projects/devtools/skillvfx/ui/SkillVfx3dAuthoringWorldRenderer.java")),initializer=java.nio.file.Files.readString(root.resolve("devtools/src/client/java/io/github/gyai/projects/devtools/ProjectSDevTools.java"));assert editor.contains("GLFW.GLFW_KEY_Z")&&editor.contains("GLFW.GLFW_KEY_Y")&&editor.contains("3D編集")&&editor.contains("syncLocalPreview");assert authoring.contains("Alt+ドラッグ")&&authoring.contains("CameraRenderState")&&!authoring.contains("getLookAngle")&&!authoring.contains("grabMouse")&&!authoring.contains("KeyMapping");assert renderer.contains("screen.updateCamera(camera)")&&renderer.contains("PrimitiveType.BEZIER")&&renderer.contains("controls.size()")&&renderer.contains("command.b() == null");assert initializer.contains("SkillVfx3dAuthoringWorldRenderer.register()")&&!java.nio.file.Files.readString(root.resolve("client-core/src/client/java/io/github/gyai/projects/client/ProjectSClient.java")).contains("SkillVfx3dAuthoring");}catch(java.io.IOException e){throw new AssertionError(e);}
